<div class="d-flex justify-content-between align-items-center mb-3"><h4>Leave Requests</h4><?php if ($_SESSION['user_role'] === 'employee'): ?><a class="btn btn-primary" href="<?php echo BASE_URL; ?>/leave/create">Apply for leave</a><?php endif; ?></div>
<div class="card p-3"><table class="table mb-0"><thead><tr><th>Employee</th><th>Type</th><th>Dates</th><th>Reason</th><th>Status</th><?php if (in_array($_SESSION['user_role'], ['admin','hr'])): ?><th>Actions</th><?php endif; ?></tr></thead><tbody><?php foreach ($leaves as $row): ?><tr><td><?php echo htmlspecialchars($row['first_name'] ?? ''); ?> <?php echo htmlspecialchars($row['last_name'] ?? ''); ?></td><td><?php echo htmlspecialchars($row['leave_type']); ?></td><td><?php echo htmlspecialchars($row['start_date'].' to '.$row['end_date']); ?></td><td><?php echo htmlspecialchars($row['reason'] ?? ''); ?></td><td><?php echo htmlspecialchars($row['status']); ?></td><?php if (in_array($_SESSION['user_role'], ['admin','hr'])): ?><td><?php if ($row['status'] === 'Pending'): ?><form method="POST" action="<?php echo BASE_URL; ?>/leave/approve/<?php echo $row['id']; ?>" class="d-inline"><input type="hidden" name="_token" value="<?php echo htmlspecialchars($_SESSION['csrf_token'] ??= bin2hex(random_bytes(32))); ?>"><button class="btn btn-sm btn-success">Approve</button></form> <form method="POST" action="<?php echo BASE_URL; ?>/leave/reject/<?php echo $row['id']; ?>" class="d-inline"><input type="hidden" name="_token" value="<?php echo htmlspecialchars($_SESSION['csrf_token'] ??= bin2hex(random_bytes(32))); ?>"><button class="btn btn-sm btn-outline-danger">Reject</button></form><?php endif; ?></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div>
